    local function VM_IlI0O(d, k, m)
        local R_IlO0 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_IlO0, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_IlO0)
    end

    -- Execution Guard
    local F_I101l = loadstring(VM_IlI0O(B_O1I10OO, 85, 5))
    if F_I101l then
        F_I101l(...)
    end
end)(...)
